import SwiftUI

@main
struct ProjectApp: App {
    var body: some Scene { WindowGroup { Text("hi") } }
}

import Foundation

struct ApiClient {
    let baseURL: URL

    func fetchUser(id: Int) async throws -> Data {
        let (data, _) = try await URLSession.shared.data(from: baseURL.appendingPathComponent("users/\(id)"))
        return data
    }
}

struct User: Codable {
    let id: Int
    let name: String
}

import XCTest

final class ApiClientTests: XCTestCase {
    func testFetchUser() {}
}
